-- Auto-generated by scripts/curriculum/build-level-sql.mjs -- do not
-- hand-edit the lesson content below; regenerate from the source plan
-- JSON instead if something needs to change.

do $$
declare
  v_course_id uuid := '566df4af-2367-4473-b090-d3ad9269c291';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Reading What the Numbers Say', 'The existing lessons cover getting a channel up and getting a video clicked. This one is about what happens after the click — the only honest way to know whether any of it is working.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Finding Your Way Around YouTube Analytics', 'YouTube''s own guide to Analytics in YouTube Studio — where the numbers live and which ones mean something. Under 6 minutes.', 'https://www.youtube.com/watch?v=J1t34uTT0iA', 1,
      array['Find impressions, click-through rate, average view duration and watch time', 'Explain what each number tells you about a different part of the video', 'Diagnose whether a video failed at the thumbnail or at the content'],
      'Every creator who grows reads their analytics. Every creator who guesses stays small. The good news is that four numbers do almost all the work, and each one points at a different problem.

IMPRESSIONS — how many times YouTube showed your thumbnail to someone. Low impressions means YouTube is not offering the video at all, usually because it has not found an audience for it yet.

CLICK-THROUGH RATE (CTR) — of the people shown it, how many clicked. This measures your THUMBNAIL AND TITLE, nothing else. A low CTR with high impressions means YouTube gave you the chance and the packaging did not earn the click.

AVERAGE VIEW DURATION and AVERAGE PERCENTAGE VIEWED — how long people actually stayed. This measures the VIDEO, and it is the number YouTube cares about most, because its business is keeping people watching.

WATCH TIME — total hours. This is the one that counts toward monetisation.

HERE IS THE DIAGNOSTIC THAT MAKES ANALYTICS USEFUL:
- High CTR, low retention → the packaging over-promised. People clicked and left. This is the most damaging combination, because YouTube learns not to recommend you.
- Low CTR, high retention → the video is good and nobody is clicking. Fix the thumbnail and title; consider re-uploading the packaging, not the video.
- Both low → the topic is wrong for your audience.
- Both high → make more of exactly this.

THE AUDIENCE RETENTION GRAPH is the single most useful screen on YouTube. It shows where people left. A steep drop in the first thirty seconds means your intro is too long — almost always the problem for new creators. A dip in the middle means a boring section you can cut next time. A spike means people rewatched something, which is worth understanding and repeating.

COMPARE AGAINST YOURSELF, not against big channels. Your last ten videos are the only fair benchmark, and YouTube Studio shows exactly that comparison.

AND GIVE A VIDEO TIME. Judging performance after two hours tells you nothing; YouTube keeps testing a video for days or weeks. Check at 48 hours, then at seven days.',
      'Open YouTube Studio on any channel you can access — your own, or a friend''s who will let you look. Write down four numbers for the most recent video: impressions, CTR, average percentage viewed and watch time. Then open the audience retention graph and note the timestamp of the biggest drop. Watch your own video at that exact moment and write one sentence on why someone left there.',
      '[{"question":"A video has a high click-through rate but very low average view duration. What does that mean?","options":["The thumbnail and title promised more than the video delivered","The video is too short","YouTube is not showing it to enough people","The topic is unpopular"],"correct_index":0},{"question":"Which number measures your thumbnail and title specifically?","options":["Click-through rate","Watch time","Average view duration","Subscriber count"],"correct_index":0}]'::jsonb),
    (v_m1, 'New Viewers Versus the Ones Who Come Back', 'YouTube''s own explanation of new and returning viewers — the difference between reaching people and keeping them. About 6 minutes.', 'https://www.youtube.com/watch?v=NSIfTsi7wTk', 2,
      array['Tell the difference between reach and loyalty in your analytics', 'Say which kind of video brings new viewers and which keeps existing ones', 'Plan a mix instead of chasing one number'],
      'A channel needs two different things, and most creators only chase one.

NEW VIEWERS are reach. They arrive from search, from suggested videos, from a thumbnail that caught their eye. Broad, beginner-friendly, curiosity-driven videos bring them.

RETURNING VIEWERS are the business. They come back because they trust you, they watch more of each video, they subscribe, they buy what you recommend, and YouTube treats their behaviour as a strong signal. Series, in-depth videos and anything with a recognisable format brings them back.

A CHANNEL THAT IS ALL NEW VIEWERS is a channel of one-hit videos — big spikes, then silence, and no audience underneath. A CHANNEL THAT IS ALL RETURNING VIEWERS is comfortable and shrinking. You need both, deliberately: roughly one reach-focused video for every two that serve the people already there is a reasonable starting mix, adjusted by what your own analytics show.

SUBSCRIBERS ARE NOT THE GOAL, and this is worth internalising early. A subscriber who never watches is worth nothing — YouTube shows your video to people it thinks will watch it, not to everyone who once clicked subscribe. Returning viewers matter; the subscriber number is vanity by comparison. Do not buy subscribers, and be sceptical of anyone selling them.

FOR A KENYAN CREATOR SPECIFICALLY, two things are worth knowing. First, your audience geography is in this same analytics screen, and it changes what monetisation is worth — ad rates vary enormously by country, so a channel with mostly Kenyan viewers earns far less per thousand views than one with viewers in the US or UK. That is not a reason to fake an audience; it is a reason to plan for sponsorship, services or your own products rather than ad revenue alone. Second, most of your viewers are on phones with limited data, so short, dense videos often outperform long ones locally.

AND WATCH THE TRENDS, not one video. One video going wide is luck. Returning viewers climbing month over month is a channel being built.',
      'In YouTube Studio, open the Audience tab and find the split between new and returning viewers, plus the top countries. Write down both. Then list your last six videos and mark each as reach (aimed at strangers) or loyalty (aimed at people who already watch). If every one is the same kind, plan your next video as the other kind.',
      '[{"question":"Why is subscriber count a weaker signal than returning viewers?","options":["A subscriber who never watches counts for nothing — YouTube recommends by watching behaviour","Subscriber counts are often inaccurate","Subscribers cannot be tracked in analytics","Subscribers only matter for monetisation"],"correct_index":0},{"question":"What does a channel with only new viewers and no returning ones look like?","options":["Occasional spikes with no audience being built underneath","Steady, predictable growth","A channel ready for monetisation","A channel with high retention"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Getting Paid', 'The reason most people start a channel, and the part the tutorials usually skip until it is too late to plan for.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'The YouTube Partner Programme', 'YouTube''s own explanation of how creators get paid — what you have to reach, and what happens once you do. About 4 minutes.', 'https://www.youtube.com/watch?v=om2WiDsHLso', 1,
      array['State the thresholds for joining the Partner Programme', 'Name the ways a channel earns beyond advertising', 'Set up what you need to actually receive money in Kenya'],
      'Monetisation is not automatic and it is not fast. Knowing the real thresholds early stops you being discouraged by the wrong things.

THE MAIN ROUTE INTO THE PARTNER PROGRAMME has historically been 1,000 subscribers plus 4,000 valid public watch hours in the past twelve months, with a Shorts route as an alternative. YouTube adjusts these thresholds and has added lower entry tiers for some features, so CHECK THE CURRENT REQUIREMENTS IN YOUTUBE STUDIO rather than trusting any video, including this one — the Monetisation tab shows your live progress against whatever the rules are today.

You also need an AdSense account, two-step verification on, and no active Community Guidelines strikes.

WHAT YOU EARN FROM depends on the country of the people watching, and this matters enormously here. Advertising rates in Kenya are a fraction of those in the US or UK, so a Kenyan channel with 100,000 views a month earns far less than the figures quoted in most YouTube-money videos, which are made by American creators for American audiences. Plan on that basis and you will not be disappointed.

WHICH IS WHY ADS SHOULD NOT BE THE PLAN. The creators who actually earn in this market do it through:
- BRAND DEALS, which pay for a specific engaged audience rather than raw views. A channel of 5,000 people who trust you is genuinely sellable.
- SELLING YOUR OWN THING — a service, a class, a product. The channel is the marketing.
- CLIENT WORK the channel proves you can do. A video editor with a channel gets hired because of it.
- Affiliate links, memberships and Super Thanks, which stack up slowly.

PRACTICALLY, FOR PAYOUT: AdSense pays into a bank account and has a payment threshold you must cross before anything is released, and you will need to complete tax information. Set the account up properly with your real legal name matching your bank details — mismatches are a common reason payments are held.

AND KNOW THAT AD REVENUE IS THE SLOWEST ROUTE, not the first one. Most channels that earn well earned something else first.',
      'Open YouTube Studio and find the Monetisation tab, which shows the current requirements and exactly how far along you are on each. Write down both thresholds and your real progress. Then, separately, write down the three ways your channel could earn money that do NOT depend on ad revenue, given the specific audience you are building.',
      '[{"question":"Why do most YouTube-earnings figures overstate what a Kenyan channel makes?","options":["Ad rates depend on where viewers are, and are far lower for a mostly Kenyan audience","Kenyan channels are not eligible for the Partner Programme","YouTube pays creators outside the US less per view for the same audience","Kenyan viewers watch shorter videos"],"correct_index":0},{"question":"Where should you check the current monetisation requirements?","options":["The Monetisation tab in YouTube Studio, which shows live progress against today''s rules","Any recent YouTube tutorial video","The subscriber count on your channel page","Your AdSense dashboard"],"correct_index":0}]'::jsonb),
    (v_m2, 'Shorts, and How They Earn Differently', 'YouTube''s own guide to Shorts in the Partner Programme — eligibility, how revenue sharing works, and what the analytics mean. Under 5 minutes.', 'https://www.youtube.com/watch?v=xMs4e9esYkg', 2,
      array['Explain how Shorts revenue differs from long-form ad revenue', 'Decide when a Short is the right format and when it is not', 'Use Shorts to find an audience without wrecking your channel'],
      'Shorts are the fastest way to be seen and the slowest way to be paid. Both halves of that matter.

HOW THE MONEY DIFFERS: long-form videos earn from ads played on that video. Shorts earn from a pool — advertising revenue across the Shorts feed is collected, music licensing is paid out of it, and what remains is shared among creators by their share of views. The practical result is that Shorts earn far less per view than long-form. Not a little less. A lot.

SO WHAT ARE THEY FOR? DISCOVERY. Shorts reach people who have never heard of you, at a scale long-form rarely matches for a new channel. The strategy that works is to use Shorts to get found and long-form to build the relationship and the income. A Short that sends someone to a long video has done its job.

THE TRAP IS AN AUDIENCE THAT ONLY WATCHES SHORTS. If everyone who finds you swipes past in fifteen seconds and never watches anything longer, you can have a large subscriber count, very little watch time, and almost no income. Plenty of channels are in exactly that position. Watch your new-versus-returning split and your long-form views, not the subscriber number.

MAKE THE HANDOVER DELIBERATE: end a Short by naming the longer video, pin a comment linking to it, and cover topics in Shorts that have a natural longer version.

AND FOR A KENYAN CREATOR, Shorts have one real advantage worth using: they are cheap to make and cheap for your audience to watch on limited data. A phone, decent light and a clear idea is genuinely enough. Use that to test which topics land before you spend a day making something long.

CHECK ELIGIBILITY IN YOUTUBE STUDIO, because Shorts have their own route into the Partner Programme with its own view threshold, and the numbers change.',
      'Take one long video idea and cut or plan a 30-second Short from its single most useful moment. Publish both, with the Short naming the long video at the end and a pinned comment linking to it. After a week, compare the views on each and, more importantly, how many people who watched the Short went on to watch the long one.',
      '[{"question":"How does Shorts revenue work?","options":["Revenue is pooled across the Shorts feed and shared by view share, earning far less per view than long-form","Each Short earns from ads played on that specific Short, like long-form","Shorts cannot be monetised at all","Shorts earn more per view than long-form videos"],"correct_index":0},{"question":"What is the risk of a channel that grows only through Shorts?","options":["A large subscriber count with little watch time and almost no income","YouTube removes the channel from search","Shorts viewers cannot subscribe","The channel becomes ineligible for the Partner Programme"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
